def seed_system_palettes(apps, schema_editor):
    """Create one row of every stock palette for every existing tenant."""
    ThemePalette = apps.get_model("admin_ops", "ThemePalette")
    Tenant = apps.get_model("persistence", "Tenant")

    for tenant in Tenant.objects.all():
        for key, (label, dark, light) in _SEED_TOKENS.items():
            ThemePalette.objects.create(
                tenant=tenant,
                key=key,
                label=label,
                is_system=True,
                dark_tokens=dark,
                light_tokens=light,
                token_keys_version="v1",
            )


def unseed_system_palettes(apps, schema_editor):
    ThemePalette = apps.get_model("admin_ops", "ThemePalette")
    ThemePalette.unscoped.filter(is_system=True).delete()

